#include <iostream>

class Animal {
public:
    virtual ~Animal() = default;
    virtual void speak() const = 0;
};

class Dog : public Animal {
public:
    void speak() const override {
        std::cout << "Dog: Woof\n";
    }
};

class Cat : public Animal {
public:
    void speak() const override {
        std::cout << "Cat: Meow\n";
    }
};

int main() {
    Dog d;
    Cat c;
    Animal* animals[2] = {&d, &c};

    for (Animal* a : animals) {
        // Dereferences pointer -> vptr -> vtable offset -> executes speak
        a->speak();
    }
    return 0;
}

#include <iostream>
#include <iomanip>
#include <vector>
#include <memory>
#include <string>
#include <typeinfo>

class Employee {
private:
    std::string name;
public:
    explicit Employee(std::string n) : name(std::move(n)) {}
    virtual ~Employee() = default;

    const std::string& getName() const { return name; }
    virtual double earnings() const = 0;
    virtual void print() const {
        std::cout << "Employee: " << name << "\n";
    }
};

class SalariedEmployee : public Employee {
private:
    double weeklySalary;
public:
    SalariedEmployee(std::string n, double salary)
        : Employee(std::move(n)), weeklySalary(salary) {}

    double earnings() const override { return weeklySalary; }
    void print() const override {
        std::cout << "Salaried Employee: " << getName()
                  << ", Weekly Salary: $" << weeklySalary << "\n";
    }
};

class BasePlusCommissionEmployee : public Employee {
private:
    double grossSales;
    double commissionRate;
    double baseSalary;
public:
    BasePlusCommissionEmployee(std::string n, double sales, double rate, double base)
        : Employee(std::move(n)), grossSales(sales), commissionRate(rate), baseSalary(base) {}

    double getBaseSalary() const { return baseSalary; }
    void setBaseSalary(double newBase) { baseSalary = newBase; }

    double earnings() const override {
        return baseSalary + (grossSales * commissionRate);
    }

    void print() const override {
        std::cout << "Base-Salaried Commission Employee: " << getName()
                  << ", Base Salary: $" << baseSalary << "\n";
    }
};

int main() {
    std::cout << std::fixed << std::setprecision(2);

    std::vector<std::unique_ptr<Employee>> staff;
    staff.push_back(std::make_unique<SalariedEmployee>("Alice", 800.00));
    staff.push_back(std::make_unique<BasePlusCommissionEmployee>("Bob", 5000.00, 0.04, 300.00));

    for (const auto& emp : staff) {
        emp->print();

        // Downcast to give 10% base salary bonus
        auto* basePlusPtr = dynamic_cast<BasePlusCommissionEmployee*>(emp.get());
        if (basePlusPtr != nullptr) {
            double oldBase = basePlusPtr->getBaseSalary();
            std::cout << "Old base salary: $" << oldBase << "\n";
            basePlusPtr->setBaseSalary(oldBase * 1.10);
            std::cout << "New base salary with 10% increase: $" 
                      << basePlusPtr->getBaseSalary() << "\n";
        }

        std::cout << "Total earnings: $" << emp->earnings() << "\n\n";
    }

    for (const auto& emp : staff) {
        bool isBasePlus = (typeid(*emp) == typeid(BasePlusCommissionEmployee));
        std::cout << emp->getName() << " is BasePlus: " 
                  << (isBasePlus ? "true" : "false") << "\n";
    }

    return 0;
}
